<?php require_once __DIR__.'/../includes/functions.php'; require_login(['admin','manager']); verify_csrf(); $pdo=db(); if(role()==='admin'&&isset($_POST['add'])){$pdo->prepare('INSERT INTO holidays (date,name,active) VALUES (?,?,1)')->execute([$_POST['date'],trim($_POST['name'])]);flash('ok','تمت الإضافة');header('Location: holidays.php');exit;} if(role()==='admin'&&isset($_POST['upd'])){$pdo->prepare('UPDATE holidays SET date=?,name=?,active=? WHERE id=?')->execute([$_POST['date'],trim($_POST['name']),(int)$_POST['active'],(int)$_POST['id']]);flash('ok','تم التعديل');header('Location: holidays.php');exit;} $rows=$pdo->query('SELECT * FROM holidays ORDER BY date DESC')->fetchAll();$title='العطل';include __DIR__.'/../includes/header.php'; ?><div class='card p-3'><a href='dashboard.php' class='btn btn-sm btn-outline-secondary mb-2'>رجوع</a><?php if(role()==='admin'): ?><form method='post' class='row g-2 mb-2'><input type='hidden' name='<?= e($config['security']['csrf_key']) ?>' value='<?= e(csrf_token()) ?>'><div class='col'><input type='date' class='form-control' name='date' required></div><div class='col'><input class='form-control' name='name'></div><div class='col'><button class='btn btn-dark w-100' name='add' value='1'>إضافة</button></div></form><?php endif; ?><table class='table table-bordered table-sm'><tr><th>ID</th><th>Date</th><th>Name</th><th>Active</th><th></th></tr><?php foreach($rows as $r): ?><tr><form method='post'><input type='hidden' name='<?= e($config['security']['csrf_key']) ?>' value='<?= e(csrf_token()) ?>'><input type='hidden' name='id' value='<?= $r['id'] ?>'><td><?= $r['id'] ?></td><td><input type='date' name='date' value='<?= e($r['date']) ?>' <?= role()!=='admin'?'readonly':'' ?>></td><td><input name='name' value='<?= e($r['name']) ?>' <?= role()!=='admin'?'readonly':'' ?>></td><td><select name='active' <?= role()!=='admin'?'disabled':'' ?>><option value='1' <?= $r['active']?'selected':'' ?>>1</option><option value='0' <?= !$r['active']?'selected':'' ?>>0</option></select></td><td><?php if(role()==='admin'): ?><button class='btn btn-sm btn-primary' name='upd' value='1'>حفظ</button><?php endif; ?></td></form></tr><?php endforeach; ?></table></div><?php include __DIR__.'/../includes/footer.php';
